// ─── File: FactoriesDemo.java ───
package com.bank.factories;

import java.math.BigDecimal;
import java.util.logging.*;

public class FactoriesDemo {
    private static final Logger log = Logger.getLogger(FactoriesDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // PLAIN FACTORY: one product
        SettlementStrategy s = SettlementFactory.create(TradeType.EQUITY);
        log.info(() -> "Factory → single product: " + s.getClass().getSimpleName());

        // ABSTRACT FACTORY: a whole matching family (regulatory)
        DocumentFactory regulatory = new RegulatoryFactory();
        renderStatement(regulatory, "SAV2001", new BigDecimal("949950"));

        // Swap the ENTIRE family by swapping one factory (customer)
        DocumentFactory customer = new CustomerFactory();
        renderStatement(customer, "SAV2001", new BigDecimal("949950"));
    }

    // Client depends ONLY on the abstract factory + abstract products
    private static void renderStatement(DocumentFactory factory, String acct, BigDecimal balance) {
        Header header = factory.createHeader();
        Formatter formatter = factory.createFormatter();
        Footer footer = factory.createFooter();
        log.info(() -> header.render() + " | " + acct + " balance=" + formatter.money(balance)
            + " | " + footer.render());
    }
}

enum TradeType { EQUITY, FX }

// ─── PLAIN FACTORY: single product ───
interface SettlementStrategy { }
class EquitySettlement implements SettlementStrategy { }
class SettlementFactory {
    static SettlementStrategy create(TradeType t) {
        return switch (t) { case EQUITY -> new EquitySettlement(); default -> throw new IllegalArgumentException(); };
    }
}

// ─── ABSTRACT FACTORY: related product interfaces (a family) ───
interface Header   { String render(); }
interface Formatter{ String money(BigDecimal amount); }
interface Footer   { String render(); }

// family A: regulatory products
class RegulatoryHeader   implements Header    { public String render(){ return "RBI REGULATORY FILING"; } }
class RegulatoryFormatter implements Formatter{ public String money(BigDecimal a){ return "INR " + a.setScale(2); } }
class RegulatoryFooter   implements Footer    { public String render(){ return "Filed per RBI circular 2024-X"; } }

// family B: customer products
class CustomerHeader   implements Header    { public String render(){ return "Your Account Statement"; } }
class CustomerFormatter implements Formatter{ public String money(BigDecimal a){ return "Rs." + a; } }
class CustomerFooter   implements Footer    { public String render(){ return "Thank you for banking with us!"; } }

// ─── THE ABSTRACT FACTORY interface ───
interface DocumentFactory {
    Header createHeader();
    Formatter createFormatter();
    Footer createFooter();
}
// each concrete factory produces ONE consistent family
class RegulatoryFactory implements DocumentFactory {
    public Header createHeader() { return new RegulatoryHeader(); }
    public Formatter createFormatter() { return new RegulatoryFormatter(); }
    public Footer createFooter() { return new RegulatoryFooter(); }
}
class CustomerFactory implements DocumentFactory {
    public Header createHeader() { return new CustomerHeader(); }
    public Formatter createFormatter() { return new CustomerFormatter(); }
    public Footer createFooter() { return new CustomerFooter(); }
}

class BankLogFormatter extends Formatter2 { }
// (helper formatter below to avoid clash with domain Formatter)
abstract class Formatter2 extends java.util.logging.Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
```

Note: the domain already uses a product interface named Formatter for the Abstract Factory family, so the log formatter is named BankLogFormatter extending a small Formatter2 helper to avoid a name clash in this single-file demo; in a real multi-file project the two live in different packages and need no rename.
